(function(root){
'use strict';
function rng(seed){let s=seed>>>0;return ()=>{s=(1664525*s+1013904223)>>>0;return (s+.5)/4294967296}}
function synthetic(seed=42,n=480){let r=rng(seed),p=100;return Array.from({length:n},(_,i)=>{let z=Math.sqrt(-2*Math.log(r()))*Math.cos(2*Math.PI*r());let drift=i<160?.0009:i<320?-.0007:.0001;p*=Math.exp(drift+z*.012);return {date:new Date(Date.UTC(2024,0,1+i)).toISOString().slice(0,10),close:p}})}
function simulate(o){let {capital,risk,entry,stop,target,exit,fee,slip,leverage,side,borrow,days}=o;for(let k of Object.keys(o))if(k!=='side'&&!Number.isFinite(o[k]))throw Error('Tous les paramètres doivent être numériques.');if(capital<=0||risk<=0||risk>10||entry<=0||stop<=0||target<=0||exit<=0||leverage<1||fee<0||slip<0||borrow<0||days<0)throw Error('Vérifiez les valeurs : prix et capital positifs, risque entre 0 et 10 %.');let sign=side==='short'?-1:1;if((entry-stop)*sign<=0||(target-entry)*sign<=0)throw Error('Long : stop < entrée < objectif. Short : objectif < entrée < stop.');let costRate=(fee+slip)/10000,perRisk=Math.abs(entry-stop)+(entry+stop)*costRate+entry*borrow/100*days/365*(side==='short');let q=Math.min(capital*risk/100/perRisk,capital*leverage/entry);let costs=q*(entry+exit)*costRate+q*entry*borrow/100*days/365*(side==='short');let pnl=q*(exit-entry)*sign-costs;let loss=q*perRisk;let reward=q*(target-entry)*sign-q*(entry+target)*costRate-q*entry*borrow/100*days/365*(side==='short');return {q,notional:q*entry,margin:q*entry/leverage,pnl,costs,loss,reward,rr:reward/loss,equity:capital+pnl}}
function backtest(data,o={}){let {fast=15,slow=60,fee=5,slip=3,borrow=3,mode='both',strategy='trend',capital=10000,start=0}=o;if(fast<2||slow<=fast||slow>=data.length-2||capital<=0||fee<0||slip<0||borrow<0)throw Error('Fenêtres : 2 ≤ rapide < lente < nombre de lignes − 2.');let sum=[0];data.forEach(x=>sum.push(sum.at(-1)+x.close));let begin=Math.max(slow+1,start),equity=capital,peak=capital,dd=0,pos=0,units=0,trade=null,trades=[],curve=[{date:data[begin-1].date,value:capital}],returns=[],costs=0;const rate=(fee+slip)/10000;
for(let i=begin;i<data.length;i++){let before=equity,move=pos*units*(data[i].close-data[i-1].close),carry=pos<0?units*data[i-1].close*borrow/100/365*(Math.max(1,(Date.parse(data[i].date)-Date.parse(data[i-1].date))/86400000)):0;equity+=move-carry;costs+=carry;if(trade)trade.pnl+=move-carry;let a=(sum[i]-sum[i-fast])/fast,b=(sum[i]-sum[i-slow])/slow;let signal=a>b?1:a<b?-1:0;if(strategy==='revert')signal=-signal;if(mode==='long'&&signal<0)signal=0;if(i===data.length-1||equity<=0)signal=0;
if(signal!==pos){if(pos!==0){let c=units*data[i].close*rate;equity-=c;costs+=c;trade.pnl-=c;trade.exit=data[i].date;trades.push(trade);trade=null}if(signal!==0&&equity>0){units=equity/(data[i].close*(1+rate));let c=units*data[i].close*rate;equity-=c;costs+=c;trade={entry:data[i].date,side:signal,pnl:-c}}pos=signal}peak=Math.max(peak,equity);dd=Math.max(dd,(peak-equity)/peak);returns.push(equity/before-1);curve.push({date:data[i].date,value:equity});if(equity<=0)break}
let wins=trades.filter(t=>t.pnl>0),profit=wins.reduce((a,t)=>a+t.pnl,0),loss=-trades.filter(t=>t.pnl<0).reduce((a,t)=>a+t.pnl,0);let end=begin+curve.length-2;let benchmark=capital/(1+rate)*data[end].close/data[begin].close*(1-rate);return {end,equity,return:equity/capital-1,dd,costs,trades,winRate:trades.length?wins.length/trades.length:0,pf:loss?profit/loss:profit?Infinity:null,curve,benchmark,begin,returns}}
function parseCSV(text){let lines=text.replace(/^\uFEFF/,'').trim().split(/\r?\n/);if(lines.length<83||lines.length>10001)throw Error('Importez 82 à 10 000 observations quotidiennes.');let sep=lines[0].includes(';')?';':',';let heads=lines.shift().toLowerCase().split(sep).map(x=>x.trim());let di=heads.indexOf('date'),ci=heads.indexOf('close');if(di<0||ci<0)throw Error('En-têtes requis : date,close (ou date;close).');let last='';return lines.map((l,i)=>{let cells=l.split(sep),date=cells[di]?.trim(),raw=cells[ci]?.trim(),close=Number(sep===';'?raw?.replace(',','.'):raw);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date||date<=last||!Number.isFinite(close)||close<=0)throw Error('Ligne '+(i+2)+' : date ISO réelle, unique, croissante et clôture positive requises.');last=date;return {date,close}})}
const api={rng,synthetic,simulate,backtest,parseCSV};if(typeof module!=='undefined')module.exports=api;root.Engine=api;
})(typeof globalThis!=='undefined'?globalThis:this);
